```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT per, service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abn' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE (service_name='search' AND span_name='rate.Rate/GetRates') OR (service_name='rate' AND span_name='rate.Rate/GetRates') GROUP BY ALL ORDER BY span_name, service_name, per",
          "claim": "search's client span for rate.Rate/GetRates rose from 7.7ms to 2596ms p95, while rate's server span stayed about 1ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT per, count(*) n, approx_quantile(start_gap,0.5)/1e6 med_start_gap_ms, approx_quantile(end_gap,0.5)/1e6 med_end_gap_ms FROM (SELECT 'abn' per, epoch_ns(c.time)-epoch_ns(s.time) AS start_gap, (epoch_ns(c.time)+c.duration)-(epoch_ns(s.time)+s.duration) AS end_gap FROM abnormal_traces c JOIN abnormal_traces s ON c.span_id=s.parent_span_id AND c.trace_id=s.trace_id WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' AND s.service_name='rate' UNION ALL SELECT 'norm', epoch_ns(c.time)-epoch_ns(s.time), (epoch_ns(c.time)+c.duration)-(epoch_ns(s.time)+s.duration) FROM normal_traces c JOIN normal_traces s ON c.span_id=s.parent_span_id AND c.trace_id=s.trace_id WHERE c.service_name='search' AND c.span_name='rate.Rate/GetRates' AND s.service_name='rate') GROUP BY per",
          "claim": "Rate's server span starts about 1.56s after search's client span in the abnormal period, versus about 0.2ms normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE attr_span_kind='Client' AND service_name='search' GROUP BY ALL ORDER BY p95_ms DESC",
          "claim": "Search's other outgoing call to geo.Geo/Nearby stays at about 0.6ms p95, so only the rate path is slow."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT per, service_name, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'abn' per, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE (service_name='frontend' AND span_name='HTTP /hotels') OR (service_name='search' AND span_name='search.Search/Nearby') GROUP BY ALL ORDER BY span_name, service_name, per",
          "claim": "Frontend's HTTP /hotels p95 rose from 17.5ms to 2582ms, matching search's Nearby p95 of about 2.6s."
        }
      ]
    }
  ]
}
```

